var collection = "" + tw.epv.RequestType.Collection;
var cancelled = "" +tw.epv.Status.Canceled;
var terminated = ""+ tw.epv.Status.terminated;

tw.local.sqlStatement = new tw.object.SQLStatement();
tw.local.sqlStatement.sql="SELECT SUM(liqAmount) FROM "+tw.env.LKP_DB_Schema +".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND REQUESTTYPE = '"+collection+"' AND (REQUESTSTATUS != '"+terminated+"' AND REQUESTSTATUS != '"+cancelled+"') ;";

tw.local.sqlStatement.parameters= new tw.object.listOf.SQLParameter();
tw.local.sqlStatement.parameters[0] = new tw.object.SQLParameter();
tw.local.sqlStatement.parameters[0].value = tw.local.parentRequestNo;

